apps/web/src/app/api/profile/route.ts.numberedContent:
1: import { NextResponse } from 'next/server';
2: import { db } from '@/lib/db';
3: import { getSessionFromRequest } from '@/lib/api-auth';
4: 
5: export const dynamic = "force-dynamic";
6: 
7: export async function GET(request: Request) {
8:   try {
9:     const session = await getSessionFromRequest(request);
10:     if (!session) {
11:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
12:     }
13: 
14:     const user = await db.user.findUnique({
15:       where: { id: session.user.id },
16:       include: { institute: true },
17:     });
18: 
19:     if (!user) {
20:       return NextResponse.json({ message: 'User not found.' }, { status: 404 });
21:     }
22: 
23:     return NextResponse.json({
24:       user: {
25:         id: user.id,
26:         name: user.name,
27:         email: user.email,
28:         role: user.role,
29:         studentNumber: (user as Record<string, unknown>).studentNumber || null,
30:         avatarUrl: user.avatarUrl ?? null,
31:         bio: user.bio,
32:         phone: user.phone,
33:         department: user.department,
34:         yearLevel: user.yearLevel,
35:         coverColor: user.coverColor,
36:         instituteId: user.instituteId,
37:         institute: {
38:           code: user.institute.code,
39:           name: user.institute.name,
40:         },
41:       },
42:     });
43:   } catch (error) {
44:     console.error('PROFILE_API_ERROR', error);
45:     return NextResponse.json({ message: 'Something went wrong.' }, { status: 500 });
46:   }
47: }
48: 
49: export async function PUT(request: Request) {
50:   try {
51:     const session = await getSessionFromRequest(request);
52:     if (!session) {
53:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
54:     }
55: 
56:     const body = await request.json();
57:     const { name, bio, phone, department, yearLevel, coverColor } = body as {
58:       name?: string;
59:       bio?: string;
60:       phone?: string;
61:       department?: string;
62:       yearLevel?: string;
63:       coverColor?: string;
64:     };
65: 
66:     const updated = await db.user.update({
67:       where: { id: session.user.id },
68:       data: {
69:         ...(name ? { name } : {}),
70:         ...(bio !== undefined ? { bio } : {}),
71:         ...(phone !== undefined ? { phone } : {}),
72:         ...(department !== undefined ? { department } : {}),
73:         ...(yearLevel !== undefined ? { yearLevel } : {}),
74:         ...(coverColor !== undefined ? { coverColor } : {}),
75:       },
76:       include: { institute: true },
77:     });
78: 
79:     return NextResponse.json({
80:       user: {
81:         id: updated.id,
82:         name: updated.name,
83:         email: updated.email,
84:         role: updated.role,
85:         studentNumber: (updated as Record<string, unknown>).studentNumber || null,
86:         avatarUrl: updated.avatarUrl ?? null,
87:         bio: updated.bio,
88:         phone: updated.phone,
89:         department: updated.department,
90:         yearLevel: updated.yearLevel,
91:         coverColor: updated.coverColor,
92:         instituteId: updated.instituteId,
93:         institute: {
94:           code: updated.institute.code,
95:           name: updated.institute.name,
96:         },
97:       },
98:     });
99:   } catch (error) {
100:     console.error('PROFILE_UPDATE_ERROR', error);
101:     return NextResponse.json({ message: 'Something went wrong.' }, { status: 500 });
102:   }
103: }
