apps/web/src/app/api/public/leaderboard/.numberedContent:
1: import { NextResponse } from "next/server";
2: import { db } from "@/lib/db";
3: 
4: export const dynamic = "force-dynamic";
5: 
6: export interface PublicLeaderboardEntry {
7:   id: string;
8:   rank: number;
9:   displayName: string;
10:   avatar: string | null;
11:   points: number;
12:   exp: number;
13:   tier: string;
14:   program: string;
15: }
16: 
17: export async function GET() {
18:   try {
19:     const profiles = await db.gamificationProfile.findMany({
20:       where: {
21:         OR: [
22:           { exp: { gt: 0 } },
23:           { totalPoints: { gt: 0 } },
24:         ],
25:         student: {
26:           role: "STUDENT",
27:           isActive: true,
28:         },
29:       },
30:       select: {
31:         id: true,
32:         exp: true,
33:         totalPoints: true,
34:         levelTier: true,
35:         isLeaderboardAnonymized: true,
36:         student: {
37:           select: {
38:             id: true,
39:             name: true,
40:             avatarUrl: true,
41:             department: true,
42:             institute: {
43:               select: {
44:                 name: true,
45:                 code: true,
46:               },
47:             },
48:           },
49:         },
50:       },
51:       orderBy: [
52:         { exp: "desc" },
53:         { totalPoints: "desc" },
54:       ],
55:       take: 10,
56:     });
57: 
58:     const entries: PublicLeaderboardEntry[] = profiles.map((p, idx) => {
59:       const isAnon = p.isLeaderboardAnonymized;
60:       const points = p.exp > 0 ? p.exp : p.totalPoints;
61:       const rawTier = p.levelTier || "newcomer";
62:       const tier = rawTier.charAt(0).toUpperCase() + rawTier.slice(1);
63:       const program =
64:         p.student.department?.trim() ||
65:         p.student.institute?.name ||
66:         "General";
67: 
68:       return {
69:         id: p.student.id,
70:         rank: idx + 1,
71:         displayName: isAnon
72:           ? `Student #${p.student.id.slice(-4).toUpperCase()}`
73:           : p.student.name,
74:         avatar: isAnon ? null : p.student.avatarUrl,
75:         points,
76:         exp: points,
77:         tier,
78:         program,
79:       };
80:     });
81: 
82:     return NextResponse.json({ entries }, { status: 200 });
83:   } catch (error) {
84:     console.error("[LEADERBOARD_GET]", error);
85:     return NextResponse.json(
86:       { error: "Failed to fetch leaderboard" },
87:       { status: 500 }
88:     );
89:   }
90: }
