apps/web/src/app/api/settings/route.ts.numberedContent:
1: import { NextResponse } from "next/server";
2: import { getSession } from "@/lib/auth-session";
3: import { db } from "@/lib/db";
4: import { UserPreferences } from "@lms/types";
5: 
6: export async function PATCH(req: Request) {
7:   try {
8:     const session = await getSession();
9:     if (!session) {
10:       return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
11:     }
12: 
13:     const body = await req.json();
14:     const { preferences } = body as { preferences: Partial<UserPreferences> };
15: 
16:     if (typeof preferences !== "object" || Array.isArray(preferences) || preferences === null) {
17:       return NextResponse.json({ message: "Invalid preferences format. Expected an object." }, { status: 400 });
18:     }
19: 
20:     // Merge existing preferences with new preferences
21:     const user = await db.user.findUnique({
22:       where: { id: session.user.id },
23:       select: { preferences: true },
24:     });
25: 
26:     if (!user) {
27:       return NextResponse.json({ message: "User not found" }, { status: 404 });
28:     }
29: 
30:     let existingPrefs: Partial<UserPreferences> = {};
31:     try {
32:       existingPrefs = JSON.parse(user.preferences);
33:     } catch {
34:       // Ignore parse error, default to empty object
35:     }
36: 
37:     const mergedPrefs: UserPreferences = {
38:       ...existingPrefs,
39:       ...preferences,
40:     };
41: 
42:     const updatedUser = await db.user.update({
43:       where: { id: session.user.id },
44:       data: {
45:         preferences: JSON.stringify(mergedPrefs),
46:       },
47:     });
48: 
49:     return NextResponse.json(updatedUser);
50:   } catch (error) {
51:     console.error("[SETTINGS_UPDATE]", error);
52:     return NextResponse.json({ message: "Internal server error" }, { status: 500 });
53:   }
54: }
