apps/web/src/app/api/study-sessions/rout.numberedContent:
1: import { NextResponse } from "next/server";
2: import { db } from "@/lib/db";
3: import { requireWorkspaceSession } from "../workspace/_shared";
4: 
5: export const dynamic = "force-dynamic";
6: 
7: import { grantExp } from "@/lib/gamification/grant-exp";
8: import { EXP_VALUES, DAILY_EXP_CAPS } from "@/lib/gamification/exp-engine";
9: import { awardBadgeIfEarned } from "@/lib/gamification/badge-checker";
10: 
11: // POST: Log a new study session (Pomodoro focus time)
12: export async function POST(request: Request) {
13:   try {
14:     const { session, response } = await requireWorkspaceSession();
15:     if (response) return response;
16: 
17:     const body = await request.json();
18:     const { courseId, syllabusItemId, durationSeconds, startedAt, completedAt } = body;
19: 
20:     if (!courseId || !durationSeconds || !startedAt || !completedAt) {
21:       return NextResponse.json(
22:         { message: "Missing required fields for study session log." },
23:         { status: 400 }
24:       );
25:     }
26: 
27:     const log = await db.studySessionLog.create({
28:       data: {
29:         userId: session.user.id,
30:         courseId,
31:         syllabusItemId,
32:         durationSeconds,
33:         startedAt: new Date(startedAt),
34:         completedAt: new Date(completedAt),
35:       },
36:     });
37: 
38:     // Grant EXP for verified study sessions (≥15 mins / 900s, max 50 EXP/day)
39:     if (durationSeconds >= 900) {
40:       try {
41:         await grantExp({
42:           userId: session.user.id,
43:           amount: EXP_VALUES.study_focus_15m,
44:           reason: "Completed 15 min Focus Study Session",
45:           source: "study_session",
46:           courseId,
47:           dailyCap: DAILY_EXP_CAPS.study_session,
48:         });
49:         await awardBadgeIfEarned(session.user.id, "study-session-first");
50:       } catch (gamiErr) {
51:         console.error("GAMIFICATION_STUDY_SESSION_ERROR", gamiErr);
52:       }
53:     }
54: 
55:     return NextResponse.json(log);
56:   } catch (error) {
57:     console.error("Error logging study session:", error);
58:     return NextResponse.json(
59:       { message: "Failed to log study session." },
60:       { status: 500 }
61:     );
62:   }
63: }
64: 
65: // GET: Fetch study sessions for the user (can optionally filter by course)
66: export async function GET(request: Request) {
67:   try {
68:     const { session, response } = await requireWorkspaceSession();
69:     if (response) return response;
70: 
71:     const url = new URL(request.url);
72:     const courseId = url.searchParams.get("courseId");
73: 
74:     const where: any = { userId: session.user.id };
75:     if (courseId) {
76:       where.courseId = courseId;
77:     }
78: 
79:     const logs = await db.studySessionLog.findMany({
80:       where,
81:       orderBy: { completedAt: "desc" },
82:     });
83: 
84:     // Optionally calculate totals
85:     const totalDuration = logs.reduce((acc, log) => acc + log.durationSeconds, 0);
86: 
87:     return NextResponse.json({ logs, totalDurationSeconds: totalDuration });
88:   } catch (error) {
89:     console.error("Error fetching study sessions:", error);
90:     return NextResponse.json(
91:       { message: "Failed to fetch study sessions." },
92:       { status: 500 }
93:     );
94:   }
95: }
