apps/web/src/app/api/todo/route.ts.numberedContent:
1: import { NextRequest, NextResponse } from "next/server";
2: import { getSession } from "@/lib/auth-session";
3: import { db } from "@/lib/db";
4: 
5: // ─── Types ───
6: 
7: interface TodoItem {
8:   id: string;
9:   title: string;
10:   type: string;
11:   dueDate: string | null;
12:   createdAt: string;
13:   courseId: string;
14:   courseTitle: string;
15:   courseCode: string;
16:   courseSection: string;
17:   instructorName: string | null;
18: }
19: 
20: interface BucketedItems {
21:   noDueDate: TodoItem[];
22:   thisWeek: TodoItem[];
23:   nextWeek: TodoItem[];
24:   later: TodoItem[];
25: }
26: 
27: // ─── Helpers ───
28: 
29: function getWeekStart(now: Date): Date {
30:   const d = new Date(now);
31:   const day = d.getUTCDay();
32:   const diffToMonday = day === 0 ? -6 : 1 - day;
33:   d.setUTCDate(d.getUTCDate() + diffToMonday);
34:   d.setUTCHours(0, 0, 0, 0);
35:   return d;
36: }
37: 
38: function bucketItems(
39:   items: {
40:     id: string;
41:     title: string;
42:     type: string;
43:     dueDate: Date | null;
44:     createdAt: Date;
45:     course: {
46:       id: string;
47:       title: string;
48:       code: string;
49:       section: string;
50:       instructor: { name: string } | null;
51:     };
52:   }[]
53: ): BucketedItems {
54:   const now = new Date(Date.now());
55:   const thisWeekStart = getWeekStart(now);
56:   const thisWeekEnd = new Date(thisWeekStart);
57:   thisWeekEnd.setUTCDate(thisWeekEnd.getUTCDate() + 7);
58:   const nextWeekEnd = new Date(thisWeekEnd);
59:   nextWeekEnd.setUTCDate(nextWeekEnd.getUTCDate() + 7);
60: 
61:   const result: BucketedItems = {
62:     noDueDate: [],
63:     thisWeek: [],
64:     nextWeek: [],
65:     later: [],
66:   };
67: 
68:   for (const item of items) {
69:     const serialized: TodoItem = {
70:       id: item.id,
71:       title: item.title,
72:       type: item.type,
73:       dueDate: item.dueDate ? item.dueDate.toISOString() : null,
74:       createdAt: item.createdAt.toISOString(),
75:       courseId: item.course.id,
76:       courseTitle: item.course.title,
77:       courseCode: item.course.code,
78:       courseSection: item.course.section,
79:       instructorName: item.course.instructor?.name ?? null,
80:     };
81: 
82:     if (!item.dueDate) {
83:       result.noDueDate.push(serialized);
84:     } else if (item.dueDate >= thisWeekStart && item.dueDate < thisWeekEnd) {
85:       result.thisWeek.push(serialized);
86:     } else if (item.dueDate >= thisWeekEnd && item.dueDate < nextWeekEnd) {
87:       result.nextWeek.push(serialized);
88:     } else {
89:       result.later.push(serialized);
90:     }
91:   }
92: 
93:   return result;
94: }
95: 
96: // ─── Route Handler ───
97: 
98: export async function GET(request: NextRequest) {
99:   const session = await getSession();
100:   if (!session) {
101:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
102:   }
103: 
104:   const { searchParams } = request.nextUrl;
105:   const instituteCode = searchParams.get("institute");
106:   const courseFilter = searchParams.get("courseId") ?? "all";
107: 
108:   if (!instituteCode) {
109:     return NextResponse.json(
110:       { error: "Missing institute query parameter" },
111:       { status: 400 }
112:     );
113:   }
114: 
115:   const studentId = session.user.id;
116: 
117:   // Resolve institute
118:   const instituteRecord = await db.institute.findUnique({
119:     where: { code: instituteCode.toLowerCase() },
120:     select: { id: true },
121:   });
122: 
123:   if (!instituteRecord) {
124:     return NextResponse.json(
125:       { error: "Institute not found" },
126:       { status: 404 }
127:     );
128:   }
129: 
130:   const instituteId = instituteRecord.id;
131: 
132:   // Fetch enrollments
133:   const enrollments = await db.enrollment.findMany({
134:     where: {
135:       studentId,
136:       status: "APPROVED",
137:       course: { instituteId, isArchived: false },
138:     },
139:     select: {
140:       courseId: true,
141:       course: {
142:         select: {
143:           id: true,
144:           title: true,
145:           code: true,
146:           section: true,
147:           instructor: { select: { name: true } },
148:         },
149:       },
150:     },
151:   });
152: 
153:   let courseIds = enrollments.map((e) => e.courseId);
154: 
155:   // Apply course filter if specified
156:   if (courseFilter !== "all") {
157:     if (!courseIds.includes(courseFilter)) {
158:       return NextResponse.json(
159:         { error: "Not enrolled in this course" },
160:         { status: 403 }
161:       );
162:     }
163:     courseIds = [courseFilter];
164:   }
165: 
166:   // Fetch submissions to exclude
167:   const submissions = await db.studentSubmission.findMany({
168:     where: {
169:       studentId,
170:       syllabusItem: { courseId: { in: courseIds } },
171:     },
172:     select: { syllabusItemId: true, status: true },
173:   });
174: 
175:   const submittedIds = new Set(
176:     submissions
177:       .filter((s) =>
178:         ["SUBMITTED", "GRADED", "RETURNED"].includes(s.status)
179:       )
180:       .map((s) => s.syllabusItemId)
181:   );
182: 
183:   // Fetch pending items
184:   const rawItems = await db.syllabusItem.findMany({
185:     where: {
186:       courseId: { in: courseIds },
187:       type: { not: "MATERIAL" },
188:       id: { notIn: [...submittedIds] },
189:     },
190:     include: {
191:       course: {
192:         select: {
193:           id: true,
194:           title: true,
195:           code: true,
196:           section: true,
197:           instructor: { select: { name: true } },
198:         },
199:       },
200:     },
201:     orderBy: { createdAt: "desc" },
202:   });
203: 
204:   const buckets = bucketItems(rawItems);
205: 
206:   const enrolledCourses = enrollments.map((e) => ({
207:     id: e.course.id,
208:     title: e.course.title,
209:     code: e.course.code,
210:   }));
211: 
212:   return NextResponse.json({
213:     items: buckets,
214:     enrolledCourses,
215:     serverNow: new Date(Date.now()).toISOString(),
216:   });
217: }
218:

apps/web/src/app/api/upload/route.ts.numberedContent:
1: // POST /api/upload — File upload endpoint
2: 
3: import { NextRequest, NextResponse } from "next/server";
4: import { getSession } from "@/lib/auth-session";
5: import path from "path";
6: import { writeFile, mkdir } from "fs/promises";
7: 
8: export const dynamic = "force-dynamic";
9: 
10: const ALLOWED_MIME_TYPES = new Set([
11:   // Documents
12:   "application/pdf",
13:   "application/msword",
14:   "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
15:   "application/vnd.ms-powerpoint",
16:   "application/vnd.openxmlformats-officedocument.presentationml.presentation",
17:   "application/vnd.ms-excel",
18:   "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
19:   // Images
20:   "image/jpeg",
21:   "image/png",
22:   "image/gif",
23:   "image/webp",
24:   // Archives
25:   "application/zip",
26:   "application/x-zip-compressed",
27:   // Text
28:   "text/plain",
29:   "text/csv",
30: ]);
31: 
32: const MAX_FILE_SIZE = 25 * 1024 * 1024; // 25 MB
33: 
34: function sanitizeFileName(name: string): string {
35:   return name
36:     .replace(/[^a-zA-Z0-9._-]/g, "_")
37:     .replace(/_{2,}/g, "_")
38:     .substring(0, 200);
39: }
40: 
41: export async function POST(req: NextRequest) {
42:   try {
43:     const session = await getSession();
44:     if (!session) {
45:       return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
46:     }
47: 
48:     const formData = await req.formData();
49:     const file = formData.get("file") as File | null;
50: 
51:     if (!file) {
52:       return NextResponse.json({ error: "No file provided." }, { status: 400 });
53:     }
54: 
55:     // Validate file size
56:     if (file.size > MAX_FILE_SIZE) {
57:       return NextResponse.json(
58:         { error: `File too large. Maximum size is 25 MB.` },
59:         { status: 400 }
60:       );
61:     }
62: 
63:     // Validate MIME type
64:     if (!ALLOWED_MIME_TYPES.has(file.type)) {
65:       return NextResponse.json(
66:         {
67:           error: `File type "${file.type}" is not allowed. Accepted: PDF, DOCX, PPTX, XLSX, JPG, PNG, GIF, WEBP, ZIP, TXT, CSV.`,
68:         },
69:         { status: 400 }
70:       );
71:     }
72: 
73:     // Generate unique filename
74:     const timestamp = Date.now();
75:     const safeName = sanitizeFileName(file.name);
76:     const uniqueName = `${timestamp}-${safeName}`;
77: 
78:     // 1. Try Vercel Blob if BLOB_READ_WRITE_TOKEN environment variable is present
79:     if (process.env.BLOB_READ_WRITE_TOKEN) {
80:       try {
81:         const { put } = await import("@vercel/blob");
82:         const blob = await put(`uploads/${uniqueName}`, file, {
83:           access: "public",
84:         });
85:         return NextResponse.json({
86:           url: blob.url,
87:           fileName: file.name,
88:           fileSize: file.size,
89:         });
90:       } catch (blobErr) {
91:         console.error("Vercel Blob upload failed, trying fallback strategy:", blobErr);
92:       }
93:     }
94: 
95:     // 2. For images without Vercel Blob configured, generate a portable Base64 Data URL
96:     // so images load reliably across all user sessions, domains, and devices without 404s
97:     const isImage = file.type.startsWith("image/");
98:     if (isImage && file.size <= 5 * 1024 * 1024) {
99:       const buffer = Buffer.from(await file.arrayBuffer());
100:       const base64 = buffer.toString("base64");
101:       const mimeType = file.type || "image/jpeg";
102:       const dataUrl = `data:${mimeType};base64,${base64}`;
103: 
104:       // Also save to local disk in dev as cache if writable
105:       try {
106:         const uploadDir = path.join(process.cwd(), "public", "uploads");
107:         await mkdir(uploadDir, { recursive: true });
108:         await writeFile(path.join(uploadDir, uniqueName), buffer);
109:       } catch {}
110: 
111:       return NextResponse.json({
112:         url: dataUrl,
113:         fileName: file.name,
114:         fileSize: file.size,
115:       });
116:     }
117: 
118:     // 3. Try writing to local filesystem (for larger files or documents)
119:     try {
120:       const uploadDir = path.join(process.cwd(), "public", "uploads");
121:       await mkdir(uploadDir, { recursive: true });
122: 
123:       const filePath = path.join(uploadDir, uniqueName);
124:       const buffer = Buffer.from(await file.arrayBuffer());
125:       await writeFile(filePath, buffer);
126: 
127:       return NextResponse.json({
128:         url: `/uploads/${uniqueName}`,
129:         fileName: file.name,
130:         fileSize: file.size,
131:       });
132:     } catch (fsErr) {
133:       console.warn(
134:         "Local filesystem write failed (read-only filesystem on Vercel), falling back to Data URL:",
135:         fsErr
136:       );
137: 
138:       // 4. Fallback for read-only serverless environment (Vercel without Vercel Blob configured)
139:       const buffer = Buffer.from(await file.arrayBuffer());
140:       const base64 = buffer.toString("base64");
141:       const mimeType = file.type || "application/octet-stream";
142:       const dataUrl = `data:${mimeType};base64,${base64}`;
143: 
144:       return NextResponse.json({
145:         url: dataUrl,
146:         fileName: file.name,
147:         fileSize: file.size,
148:       });
149:     }
150:   } catch (error) {
151:     console.error("Upload error:", error);
152:     return NextResponse.json(
153:       { error: "Failed to upload file." },
154:       { status: 500 }
155:     );
156:   }
157: }
