1: import { NextResponse } from "next/server";
2: import { db } from "@/lib/db";
3: import { getSession } from "@/lib/auth-session";
4: 
5: export const dynamic = "force-dynamic";
6: 
7: type RouteParams = { params: Promise<{ userId: string }> };
8: 
9: export async function GET(_req: Request, { params }: RouteParams) {
10:   const session = await getSession();
11:   if (!session) {
12:     return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
13:   }
14: 
15:   const { userId } = await params;
16: 
17:   const user = await db.user.findUnique({
18:     where: { id: userId },
19:     select: {
20:       id: true,
21:       name: true,
22:       email: true,
23:       role: true,
24:       studentNumber: true,
25:       uniqueId: true,
26:       avatarUrl: true,
27:       bio: true,
28:       phone: true,
29:       department: true,
30:       yearLevel: true,
31:       coverColor: true,
32:       createdAt: true,
33:       instituteId: true,
34:       institute: { select: { code: true, name: true } },
35:       taughtCourses: {
36:         where: { isArchived: false },
37:         select: { id: true, title: true, code: true },
38:         take: 5,
39:       },
40:       enrollments: {
41:         where: { status: "APPROVED" },
42:         select: { course: { select: { id: true, title: true, code: true } } },
43:         take: 5,
44:       },
45:       gamificationProfile: {
46:         select: {
47:           exp: true,
48:           level: true,
49:           levelTier: true,
50:           currentStreak: true,
51:           longestStreak: true,
52:           totalLoginDays: true,
53:           badges: {
54:             select: { badgeRuleId: true, earnedAt: true },
55:             orderBy: { earnedAt: "desc" },
56:             take: 6,
57:           },
58:         },
59:       },
60:     },
61:   });
62: 
63:   if (!user) {
64:     return NextResponse.json({ message: "User not found." }, { status: 404 });
65:   }
66: 
67:   // Security: only users in the same institute can view profiles
68:   const sessionUser = session.user as Record<string, unknown>;
69:   const sessionInstituteId = sessionUser.instituteId as string;
70: 
71:   if (user.instituteId !== sessionInstituteId) {
72:     return NextResponse.json({ message: "Forbidden." }, { status: 403 });
73:   }
74: 
75:   return NextResponse.json({ user });
76: }
